    h, w = len(g), len(g[0])

    # The common nonzero color forms the tile frames. Other nonzero colors
    # are the tile markers that determine which gaps to connect.
    from collections import Counter
    counts = Counter(v for row in grid for v in row if v)
    frame = counts.most_common(1)[0][0]
    markers = {(r, c): grid[r][c]
               for r in range(h) for c in range(w)
               if grid[r][c] not in (0, frame)}

    by_row, by_col = {}, {}
    for (r, c), color in markers.items():
        by_row.setdefault(r, []).append((c, color))
        by_col.setdefault(c, []).append((r, color))

    for r, items in by_row.items():
        items.sort()
        for (c1, color1), (c2, color2) in zip(items, items[1:]):
            if color1 == color2:
                for c in range(c1 + 1, c2):
                    if g[r][c] == 0:
                        g[r][c] = color1

    for c, items in by_col.items():
        items.sort()
        for (r1, color1), (r2, color2) in zip(items, items[1:]):
            if color1 == color2:
                for r in range(r1 + 1, r2):
                    if g[r][c] == 0:
                        g[r][c] = color1
    return g
